<template><v-card class="content-card pa-7"><div class="d-flex align-center mb-6"><div><h1 class="text-h4 font-weight-bold">Usuarios y roles</h1><p class="text-medium-emphasis mt-1">Administra accesos y responsabilidades del taller.</p></div><v-spacer/><v-btn color="primary" prepend-icon="mdi-account-plus" @click="openCreate">Nuevo usuario</v-btn></div><AppAlert :message="error" @clear="error=''"/><v-data-table :headers="headers" :items="users" :loading="loading"><template #item.roles="{item}"><v-chip v-for="role in item.roles" :key="role" size="small" class="mr-1">{{role}}</v-chip></template><template #item.is_active="{item}"><v-chip :color="item.is_active?'success':'error'" size="small">{{item.is_active?'Activo':'Inactivo'}}</v-chip></template><template #item.actions="{item}"><v-btn size="small" icon="mdi-key-variant" variant="text" @click="openReset(item)"/><v-btn size="small" icon="mdi-pencil" variant="text" @click="edit(item)"/></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="650"><v-card class="pa-5"><v-card-title>{{ selected?.id ? 'Editar usuario':'Nuevo usuario' }}</v-card-title><v-card-text><v-form v-model="valid" @submit.prevent="save"><v-text-field v-model.trim="form.full_name" label="Nombre completo" :rules="[v=>v?.length>=3||'Mínimo 3 caracteres']"/><v-text-field v-model.trim="form.username" label="Usuario" :rules="[v=>/^[A-Za-z0-9_.-]{3,}$/.test(v)||'Usuario inválido']"/><PasswordFields v-if="!selected?.id" v-model="form.password"/><v-switch v-if="selected?.id" v-model="form.is_active" label="Cuenta activa" color="primary"/><v-select v-model="form.roles" :items="roles" label="Roles" multiple chips :rules="[v=>v?.length||'Asigne por lo menos un rol']"/><v-btn type="submit" color="primary" :disabled="!valid" :loading="saving">Guardar</v-btn><v-btn class="ml-2" variant="text" @click="dialog=false">Cancelar</v-btn></v-form></v-card-text></v-card></v-dialog><v-dialog v-model="resetDialog" max-width="500"><v-card class="pa-5"><v-card-title>Restablecer contraseña</v-card-title><v-card-text><p class="text-medium-emphasis mb-4">Define una contraseña temporal para {{ resetTarget?.username }}. Sus sesiones activas se cerrarán.</p><v-form v-model="resetValid" @submit.prevent="resetPassword"><PasswordFields v-model="resetForm.new_password" label="Contraseña temporal"/><v-btn color="primary" type="submit" :disabled="!resetValid" :loading="resetting">Restablecer</v-btn><v-btn class="ml-2" variant="text" @click="resetDialog=false">Cancelar</v-btn></v-form></v-card-text></v-card></v-dialog></template>
<script setup>import{onMounted,ref}from'vue';import api from'../services/api';import AppAlert from'../components/AppAlert.vue';import PasswordFields from'../components/PasswordFields.vue';const roles=['Administrador','Recepcionista','Asesor de servicio','Técnico','Cliente'],headers=[{title:'Nombre',key:'full_name'},{title:'Usuario',key:'username'},{title:'Roles',key:'roles'},{title:'Estado',key:'is_active'},{title:'',key:'actions',sortable:false}],users=ref([]),loading=ref(false),saving=ref(false),error=ref(''),dialog=ref(false),valid=ref(false),selected=ref(null),resetDialog=ref(false),resetTarget=ref(null),resetValid=ref(false),resetting=ref(false),resetForm=ref({new_password:''}),empty=()=>({full_name:'',username:'',password:'',is_active:true,roles:[]}),form=ref(empty());async function load(){loading.value=true;try{users.value=(await api.get('/users')).data}catch(e){error.value=e.response?.data?.detail||'No fue posible cargar los usuarios'}finally{loading.value=false}}function openCreate(){selected.value=null;form.value=empty();dialog.value=true}function edit(user){selected.value=user;form.value={...user,roles:[...user.roles]};dialog.value=true}function openReset(user){resetTarget.value=user;resetForm.value={new_password:''};resetDialog.value=true}async function resetPassword(){resetting.value=true;try{await api.put(`/users/${resetTarget.value.id}/reset-password`,resetForm.value);resetDialog.value=false}catch(e){error.value=e.response?.data?.detail||'No fue posible restablecer la contraseña'}finally{resetting.value=false}}async function save(){saving.value=true;try{let record;if(selected.value?.id){record=(await api.patch(`/users/${selected.value.id}`,{full_name:form.value.full_name,username:form.value.username,is_active:form.value.is_active})).data;record=(await api.put(`/users/${record.id}/roles`,{roles:form.value.roles})).data;users.value=users.value.map(u=>u.id===record.id?record:u)}else{record=(await api.post('/users',{full_name:form.value.full_name,username:form.value.username,password:form.value.password,roles:form.value.roles})).data;users.value.push(record)}dialog.value=false}catch(e){error.value=e.response?.data?.detail||'No fue posible guardar'}finally{saving.value=false}}onMounted(load)</script>
